func (q *Queries) UpdateAlertOccurrence(ctx context.Context, arg UpdateAlertOccurrenceParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAlertOccurrence,
		arg.ID,
		arg.State,
		arg.TransitionSequence,
		arg.LatestEvaluationID,
		arg.Payload,
		arg.UpdatedAt,
		arg.TerminalAt,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
